<?php
require_once __DIR__.'/../config.php';require_once __DIR__.'/../botapi.php';require_once __DIR__.'/../lib/TicketAttachments.php';require_once __DIR__.'/lib/Portal.php';require_once __DIR__.'/lib/Layout.php';$ctx=rxp_context($pdo);rxp_require_perm($ctx,'support');$tracking=trim((string)($_GET['id']??$_POST['tracking']??''));$flash='';$ft='ok';$ticket=null;
function rxp_ticket(PDO$pdo,array$ctx,string$tracking):?array{if(!preg_match('/^[A-Za-z0-9_-]{1,100}$/',$tracking))return null;[$scope,$params]=rxp_customer_scope($ctx,'u');$q=$pdo->prepare("SELECT sm.*,u.bottype,u.username customer_username FROM support_message sm JOIN user u ON u.id=sm.iduser WHERE sm.Tracking=? AND $scope LIMIT 1");$q->execute(array_merge([$tracking],$params));$r=$q->fetch(PDO::FETCH_ASSOC);return$r?:null;}
if($tracking!=='')$ticket=rxp_ticket($pdo,$ctx,$tracking);
if(($_SERVER['REQUEST_METHOD']??'')==='POST'){$ticket=rxp_ticket($pdo,$ctx,$tracking);if(!$ticket)rxp_abort(404,'تیکت متعلق به محدوده شما نیست.');$answer=trim((string)($_POST['answer']??''));$hasFile=isset($_FILES['attachment'])&&($_FILES['attachment']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE;if(($answer===''&&!$hasFile)||mb_strlen($answer)>3500){$flash='پاسخ یا پیوست لازم است؛ متن حداکثر ۳۵۰۰ کاراکتر.';$ft='err';}else{try{$token=null;if(!empty($ticket['bottype'])&&in_array((string)$ticket['bottype'],$ctx['bot_tokens'],true))$token=(string)$ticket['bottype'];$attachment=null;$ticketOwner=$ctx['id'];if(!empty($ticket['bottype'])){$oq=$pdo->prepare('SELECT id_user FROM botsaz WHERE bot_token=? LIMIT 1');$oq->execute([$ticket['bottype']]);$candidate=(string)$oq->fetchColumn();if(in_array($candidate,$ctx['scope_ids'],true))$ticketOwner=$candidate;}if($ticketOwner===$ctx['id']&&$ctx['role']==='super'){[$oph,$oids]=rxp_in($ctx['scope_ids']);$oq=$pdo->prepare("SELECT refral FROM invoice WHERE id_user=? AND refral IN ($oph) ORDER BY time_sell DESC LIMIT 1");$oq->execute(array_merge([$ticket['iduser']],$oids));$candidate=(string)$oq->fetchColumn();if(in_array($candidate,$ctx['scope_ids'],true))$ticketOwner=$candidate;}if($hasFile){$attachment=RedFoxTicketAttachments::store($_FILES['attachment'],dirname(__DIR__));$q=$pdo->prepare('INSERT INTO reseller_ticket_attachments(tracking,reseller_id,uploader_type,uploader_id,storage_name,original_name,mime_type,file_size,sha256,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute([$tracking,$ticketOwner,'reseller',$ctx['id'],$attachment['storage_name'],$attachment['original_name'],$attachment['mime'],$attachment['size'],$attachment['sha256'],time()]);$attachment['id']=(int)$pdo->lastInsertId();}$resultText=$answer!==''?$answer:('[پیوست: '.($attachment['original_name']??'file').']');$q=$pdo->prepare("UPDATE support_message SET result=?,status='Answered' WHERE Tracking=? AND iduser=?");$q->execute([$resultText,$tracking,$ticket['iduser']]);if($attachment){$caption="🎟 پاسخ پشتیبانی\n".($answer!==''?$answer."\n":'')."کد پیگیری: $tracking";$resp=RedFoxTicketAttachments::send((string)$ticket['iduser'],$attachment,$caption,$token);}else{$resp=sendmessage((string)$ticket['iduser'],"🎟 <b>پاسخ پشتیبانی</b>\n\n".htmlspecialchars($answer,ENT_QUOTES,'UTF-8')."\n\nکد پیگیری: <code>".htmlspecialchars($tracking)."</code>",null,'HTML',$token);}if(!is_array($resp)||empty($resp['ok']))throw new DomainException('ثبت شد اما ارسال تلگرام ناموفق بود.');rxp_audit($pdo,$ctx,'ticket.answer',$tracking,['user'=>$ticket['iduser'],'attachment_id'=>$attachment['id']??null]);$flash='پاسخ ثبت و ارسال شد.';$ticket=rxp_ticket($pdo,$ctx,$tracking);}catch(Throwable$e){$flash=rxp_public_exception_message($e, basename(__FILE__));$ft='err';}}}

if($tracking===''||!$ticket){[$scope,$params]=rxp_customer_scope($ctx,'u');$q=$pdo->prepare("SELECT sm.Tracking,sm.iduser,sm.name_departman,sm.text,sm.time,sm.status,u.username FROM support_message sm JOIN user u ON u.id=sm.iduser WHERE $scope ORDER BY sm.time DESC LIMIT 500");try{$q->execute($params);$tickets=$q->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable$e){$tickets=[];$flash='جدول پشتیبانی در دسترس نیست.';$ft='err';}rxp_layout_start($ctx,'تیکت مشتریان','tickets.php');rxp_flash($flash,$ft);?><h1 class="rxp-title">تیکت مشتریان Scope شما</h1><div class="rxp-card"><div class="rxp-table-wrap"><table class="rxp-table"><tr><th>پیگیری</th><th>مشتری</th><th>دپارتمان</th><th>متن</th><th>زمان</th><th>وضعیت</th><th></th></tr><?php foreach($tickets as$t):?><tr><td><code><?=rxp_h($t['Tracking'])?></code></td><td><?=rxp_h($t['iduser'].' / '.$t['username'])?></td><td><?=rxp_h($t['name_departman'])?></td><td><?=rxp_h(mb_substr((string)$t['text'],0,90))?></td><td><?=rxp_h($t['time'])?></td><td><span class="rxp-badge"><?=rxp_h($t['status'])?></span></td><td><a class="rxp-btn" href="?id=<?=urlencode((string)$t['Tracking'])?>">مشاهده</a></td></tr><?php endforeach;?></table></div></div><?php rxp_layout_end();exit;}
[$aph,$aids]=rxp_in($ctx['scope_ids']);$qa=$pdo->prepare("SELECT * FROM reseller_ticket_attachments WHERE tracking=? AND reseller_id IN ($aph) ORDER BY id");$qa->execute(array_merge([$tracking],$aids));$attachments=$qa->fetchAll(PDO::FETCH_ASSOC);rxp_layout_start($ctx,'جزئیات تیکت','tickets.php');rxp_flash($flash,$ft);?><h1 class="rxp-title">تیکت <?=rxp_h($tracking)?></h1><div class="rxp-card"><table class="rxp-table"><tr><th>مشتری</th><td><a href="users.php?id=<?=urlencode((string)$ticket['iduser'])?>"><?=rxp_h($ticket['iduser'].' / '.$ticket['customer_username'])?></a></td></tr><tr><th>دپارتمان</th><td><?=rxp_h($ticket['name_departman'])?></td></tr><tr><th>پیام</th><td style="white-space:pre-wrap"><?=rxp_h($ticket['text'])?></td></tr><tr><th>پاسخ فعلی</th><td style="white-space:pre-wrap"><?=rxp_h($ticket['result']??'—')?></td></tr></table></div><?php if($attachments):?><div class="rxp-card"><h2>پیوست‌ها</h2><table class="rxp-table"><tr><th>نام</th><th>نوع</th><th>حجم</th><th>SHA</th><th></th></tr><?php foreach($attachments as$a):?><tr><td><?=rxp_h($a['original_name'])?></td><td><?=rxp_h($a['mime_type'])?></td><td><?=number_format((int)$a['file_size'])?></td><td><code><?=rxp_h(substr($a['sha256'],0,16))?>…</code></td><td><a class="rxp-btn" href="ticket_file.php?id=<?=(int)$a['id']?>">دانلود امن</a></td></tr><?php endforeach;?></table></div><?php endif;?><div class="rxp-card"><h2>ثبت پاسخ و پیوست</h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="tracking" value="<?=rxp_h($tracking)?>"><div class="rxp-field"><textarea name="answer" maxlength="3500" style="width:100%;min-height:120px" placeholder="متن پاسخ (اگر فایل دارید اختیاری)"></textarea></div><div class="rxp-field"><input type="file" name="attachment" accept="image/jpeg,image/png,image/webp,video/mp4,application/pdf,text/plain"><small>حداکثر ۸MB — JPG/PNG/WebP/MP4/PDF/TXT</small></div><button class="rxp-btn green">ارسال پاسخ</button></form></div><?php rxp_layout_end();
